+	const marker = "ADD COLUMN "
+	idx := strings.Index(stmt, marker)
+	name := strings.TrimSpace(stmt[idx+len(marker):])
+	if space := strings.IndexByte(name, ' '); space >= 0 {
+		name = name[:space]
+	}
+	return name
+}
